import copy
import sys
sys.modules['sklearn.externals.six'] = type(sys)('six')
sys.modules['sklearn.externals.six'].iteritems = lambda d: d.items()

# Simulate minimal get_params/BaseEstimator
class FakeEstimator:
    def __init__(self, with_mean=True):
        self.with_mean = with_mean
    def get_params(self, deep=True):
        return {'with_mean': self.with_mean}

class FakeEstimatorType:
    def get_params(self, deep=True):
        return {}

# Test the original clone logic
def clone_original(estimator, safe=True):
    import copy
    estimator_type = type(estimator)
    if estimator_type in (list, tuple, set, frozenset):
        return estimator_type([clone_original(e, safe=safe) for e in estimator])
    elif not hasattr(estimator, 'get_params'):
        if not safe:
            return copy.deepcopy(estimator)
        else:
            raise TypeError('Cannot clone')
    klass = estimator.__class__
    new_object_params = estimator.get_params(deep=False)
    for name, param in new_object_params.items():
        new_object_params[name] = clone_original(param, safe=False)
    new_object = klass(**new_object_params)
    params_set = new_object.get_params(deep=False)
    for name in new_object_params:
        param1 = new_object_params[name]
        param2 = params_set[name]
        if param1 is not param2:
            raise RuntimeError('Cannot clone object %s' % estimator)
    return new_object

# Test the fixed clone logic 
def clone_fixed(estimator, safe=True):
    import copy
    estimator_type = type(estimator)
    if estimator_type in (list, tuple, set, frozenset):
        return estimator_type([clone_fixed(e, safe=safe) for e in estimator])
    elif not hasattr(estimator, 'get_params') or isinstance(estimator, type):
        if not safe:
            return copy.deepcopy(estimator)
        else:
            raise TypeError('Cannot clone')
    klass = estimator.__class__
    new_object_params = estimator.get_params(deep=False)
    for name, param in new_object_params.items():
        new_object_params[name] = clone_fixed(param, safe=False)
    new_object = klass(**new_object_params)
    params_set = new_object.get_params(deep=False)
    for name in new_object_params:
        param1 = new_object_params[name]
        param2 = params_set[name]
        if param1 is not param2:
            raise RuntimeError('Cannot clone object %s' % estimator)
    return new_object

# Test 1: Original fails when param is an estimator type
print('Test 1: clone_original with estimator type as param...')
try:
    clone_original(FakeEstimator(with_mean=FakeEstimatorType))
    print('  FAIL: should have raised TypeError')
except TypeError as e:
    print('  Got expected error:', e)

# Test 2: Fixed version works
print('Test 2: clone_fixed with estimator type as param...')
try:
    result = clone_fixed(FakeEstimator(with_mean=FakeEstimatorType))
    print('  SUCCESS! with_mean =', result.with_mean)
    assert result.with_mean is FakeEstimatorType
    print('  Param preserved correctly!')
except Exception as e:
    print('  FAIL:', e)

# Test 3: Normal clone still works
print('Test 3: clone_fixed with normal params...')
try:
    result = clone_fixed(FakeEstimator(with_mean=True))
    print('  SUCCESS! with_mean =', result.with_mean)
except Exception as e:
    print('  FAIL:', e)

# Test 4: safe=True with a type should raise
print('Test 4: clone_fixed with type and safe=True...')
try:
    result = clone_fixed(FakeEstimatorType, safe=True)
    print('  FAIL: should have raised TypeError')
except TypeError:
    print('  Got expected TypeError (safe=True rejects types)')
